def compute(vars):
    feed_obligations = vars["v1"]
    construction_obligations = vars["v2"]
    total = feed_obligations + construction_obligations

    return {
        "value": total,
        "trace": {
            "feed_obligations": feed_obligations,
            "construction_obligations": construction_obligations,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None,
            },
        },
    }
